import{S as s,o as d,c as a,a9 as i,B as n}from"./chunks/framework.IJ8axLs_.js";const p="/agentsrc/images/deepseek/01-plugin-tree.svg",k=JSON.parse('{"title":"DeepSeek Harness 全景：一切皆插件的通用 agent 引擎","description":"","frontmatter":{"title":"DeepSeek Harness 全景：一切皆插件的通用 agent 引擎"},"headers":[],"relativePath":"deepseek/01-overview.md","filePath":"deepseek/01-overview.md","lastUpdated":1790217011000}'),c={name:"deepseek/01-overview.md"},g=Object.assign(c,{setup(l){const t=[{question:"下列哪一项最符合 `dsh` 的架构定位？",options:["一切皆插件，循环本身也只是默认实现","中央主循环固定，其余模块围绕它注册","循环写死在核心，扩展必须改代码","与 OpenCode 相同，runLoop 位于中心"],correct:0,explanation:'dsh 的 everything is a plugin 加无特权核心：agent-loop 只是默认实现且 swappable。B/C 是前三栏"循环写死"的模式，D 把 OpenCode 的结构与 dsh 混为一谈。'},{question:"profile 装配的层叠顺序，正确的是？",options:["home patch → bundle 层序 → profile patch → 覆盖","按包名字典序应用，与声明顺序无关","bundle 层序 → profile patch → home patch → --patch","--patch → profile patch → bundle 层序 → home patch"],correct:2,explanation:"每个 profile 从空配置起步，先按列出顺序叠 bundle，再叠 profile 自己的 cordis.patch.yml，然后是 home 级文件，命令行 --patch 权限最高。A 把 home 级提前了，D 整个倒置，B 的字典序不存在——层序由 profile 声明决定。"},{question:"`dsh --profile web --dump-config` 的用途是？",options:["打印这台机器实际会启动的配置树","导出 Web 前端的构建产物","新建一个叫 dump-config 的 profile","从当前 profile 卸载指定插件"],correct:0,explanation:"dump-config 不启动、不请求模型，只打印叠好的整棵插件树，且每一行都能被自己的 patch 替换。B 把配置树当成了构建产物，C 混淆了它和 profile 创建命令，D 把审查能力当成了管理操作。"},{question:"`sdk-minimal` 这个 bundle 的特殊之处在于？",options:["它是 base 的精简版，只装半个 base","它不用 dsh-base，单一 bundle 独占完整显式树","它只能被 Python SDK 使用，其他入口禁止","它把 agent-loop 替换成了专用循环"],correct:1,explanation:'架构文档称它为 deliberate exception：不套 dsh-base，由一个 bundle 持有完整的显式 SDK 树，用来证明从零组一棵干净的树是可行的。A 的"精简 base"说反了它的独立路线，C 没有这个入口限制，D 与循环无关。'},{question:'"Extension plugins depend on Service Definitions, never concrete providers" 这条规则直接保证了什么？',options:["扩展插件的加载顺序由依赖图自动推导","所有插件必须发布到 npm 公共仓库","Service Provider 之间禁止互相调用","换 Provider 实现时扩展插件不用改代码"],correct:3,explanation:"插件只依赖接口包（如 dsh-agent），不 import 具体 provider（如 dsh-agent-loop），所以替换实现时消费方不动。A 说的是 inject 依赖声明的另一件事，B/C 都不是这条规则的内容。"}];return(r,e)=>{const o=s("Quiz");return d(),a("div",null,[e[0]||(e[0]=i(`<h1 id="deepseek-harness-全景-一切皆插件的通用-agent-引擎" tabindex="-1">DeepSeek Harness 全景：一切皆插件的通用 agent 引擎 <a class="header-anchor" href="#deepseek-harness-全景-一切皆插件的通用-agent-引擎" aria-label="Permalink to &quot;DeepSeek Harness 全景：一切皆插件的通用 agent 引擎&quot;">​</a></h1><p>本站拆过的三个终端编程 Agent——OpenCode、Codex、Claude Code——骨架是同一个：一个写死在产品中心的主循环，工具、权限、上下文管理围绕它长出来。你要扩展，要么改核心循环，要么在它预设的钩子上挂东西。</p><p>DeepSeek 开源的 <code>dsh</code> 不在这个谱系里。它把自己放在产品的下一层：做一台可以被任意产品装配的通用 agent 引擎，服务对象是拿它当内核的产品团队。这个定位落到代码上，就是整栏的核心判断：</p><blockquote><p><strong><code>dsh</code> 的源码里没有一个不可变的中央循环可供拆解——只有一棵运行期组装出来的插件树。模型适配器、工具注册表、会话日志、agent 循环本身，全部是插件，全部可以从配置换掉。</strong></p></blockquote><p>所以这一栏的读法也变了：前三栏是&quot;拆一个主循环&quot;，这一栏是&quot;看一棵插件树怎么拼出来、怎么装配成产品&quot;。这一篇先把总地图铺开，读完你会带着三个问题的答案离开：</p><ul><li>300 多个包的 monorepo，靠什么规则组织而不散架？</li><li>同一棵插件树怎么装配出 Web、命令行、SDK、自动化协议、桌面这些产品形态？</li><li>它和前三栏同能不同构，差别到底落在哪几层？</li></ul><p>Cordis 原语、turn/step 事件流、日志投影、capability 缝这些机制细节，留给后面五篇下潜。</p><h2 id="一、第四种物种-没有特权核心" tabindex="-1">一、第四种物种：没有特权核心 <a class="header-anchor" href="#一、第四种物种-没有特权核心" aria-label="Permalink to &quot;一、第四种物种：没有特权核心&quot;">​</a></h2><p>先给一张定位表：</p><table tabindex="0"><thead><tr><th>维度</th><th>OpenCode / Codex / Claude Code</th><th>DeepSeek Harness</th></tr></thead><tbody><tr><td>定位</td><td>终端编程 Agent（面向用户的产品）</td><td>通用 agent harness（被产品装配的引擎）</td></tr><tr><td>核心抽象</td><td>一个主循环（runLoop / reactor / QueryEngine）</td><td>插件树 + 组合框架</td></tr><tr><td>循环可否换</td><td>写死在产品中心</td><td><code>agent-loop</code> 只是默认实现，swappable</td></tr><tr><td>面向</td><td>替用户写代码</td><td>装配成任意形态</td></tr></tbody></table><p><code>dsh</code> 的架构文档把这件事说得很直白：</p><blockquote><p>There is no privileged core to patch: you extend dsh by mounting a plugin beside the others, and registrations are effects that unwind when the plugin unloads.</p></blockquote><p>这段话拆开是三条设计承诺。第一，扩展的位置在树旁边新挂一个插件，不碰别人的代码；第二，每个注册都是可逆的副作用，插件卸载时它的注册整体回滚；第三，连 agent 循环本身都是插件——<code>core/agent</code> 定义 <code>Agent</code> 接口和 <code>ctx.agents</code> 注册表，<code>core/agent-loop</code> 只是实现这个接口的默认驱动。仓库的依赖规则里写着：UI、hook、工具插件一律依赖 <code>dsh-agent</code>（接口），不依赖 <code>dsh-agent-loop</code>（实现），所以 loop 换掉时其余插件毫发无损。同一层还有挂在 <code>ctx.llm</code> 的模型适配器和挂在 <code>ctx.tools</code> 的工具注册表——开头那句核心判断点名的四个部件，在源码里各占一个可换的位。</p><p>这个选择有代价。终端 Agent 的循环固定，换来的是职责单一、好维护；<code>dsh</code> 要让任意产品拿它当引擎，不同产品要不同循环、不同工具集、不同沙箱策略，循环一旦写死，通用性就没了。把&quot;循环&quot;降级成一个可替换的实现，是这个目标下的必然后果。</p><h2 id="二、仓库组织-三百个包与三条规律" tabindex="-1">二、仓库组织：三百个包与三条规律 <a class="header-anchor" href="#二、仓库组织-三百个包与三条规律" aria-label="Permalink to &quot;二、仓库组织：三百个包与三条规律&quot;">​</a></h2><p><code>dsh</code> 是一个规模可观的 pnpm monorepo。几个实测数字：<code>packages/</code> 下有 <strong>307 个</strong> <code>@deepseek-ai</code> 域内的包，按 <code>packages/&lt;组&gt;/&lt;包&gt;</code> 两级分组，共 50 多个组；<code>packages/</code> 内 TypeScript 约 <strong>75 万行</strong>（含测试；剔除测试目录约 34 万行）；加上 <code>apps/</code>、<code>scripts/</code>、<code>python/</code> 等目录，全仓 <code>.ts</code> 约 91 万行。根 <code>pnpm-workspace.yaml</code> 把它们全部编进一个 workspace：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># pnpm-workspace.yaml（节选）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">packages</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vendor/*</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # vendored Cordis 等框架包</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">packages/*/*</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 主体：50+ 组 × 每组若干包</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">native/system</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # Landlock 启动器（native addon）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">apps/*</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 产品壳：cli、web、desktop…</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">python/sdk-runtime</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Python SDK 的部署根</span></span></code></pre></div><p>单仓库 + workspace 让&quot;依赖必须跨包显式声明、按包独立发布、依赖图机器可查&quot;成为可能。<code>packages/README.md</code> 的分组表是走读地图，记不住每个组没关系，抓三条规律就够：</p><ul><li><strong><code>core/</code> 是产品 API 脊柱</strong>：<code>session</code>（会话日志）、<code>system-prompt</code>、<code>tools</code>、<code>agent</code>（Agent 接口）、<code>agent-loop</code>（默认驱动）、<code>scope</code>。这些包不讲&quot;某个能力&quot;，只讲产品内部的数据结构与循环。</li><li><strong>其余组几乎都是能力族</strong>：<code>shell</code>、<code>fs</code>、<code>subprocess</code>、<code>sandbox</code>、<code>compaction</code>、<code>subagent</code>、<code>web</code>、<code>skill</code>……每个能力 = 接口声明 + 实现 + 消费方三个角色（第五篇的专项）。</li><li><strong><code>bundle/</code> 是装配层</strong>：<code>base</code>、<code>web-app</code>、<code>headless</code>、<code>sdk-app</code>、<code>acp-app</code>、<code>sdk-minimal</code>，把上面的包组装成产品。</li></ul><p>支撑这套分工的依赖规则很硬：&quot;Extension plugins depend on Service Definitions, never concrete providers&quot;——扩展插件只依赖服务定义，绝不依赖具体实现；依赖图由脚本生成、CI 校验。包的边界是约束，不是目录美学。</p><h2 id="三、装配链-profile、bundle-与-patch" tabindex="-1">三、装配链：profile、bundle 与 patch <a class="header-anchor" href="#三、装配链-profile、bundle-与-patch" aria-label="Permalink to &quot;三、装配链：profile、bundle 与 patch&quot;">​</a></h2><p>包堆在那里还是包，一个能跑的 <code>dsh</code> 是怎么出现的？答案是<strong>按有序层叠装配出一棵插件树</strong>。三个概念：</p><ul><li><strong>profile（档）</strong>：存在 Harness home（<code>$DSH_HOME/profiles/&lt;name&gt;</code>）里的命名组合。它声明装哪些 bundle、留哪些树外插件、放一份自己的 <code>cordis.patch.yml</code>。仓库随发行带了五个模板：<code>web</code>、<code>headless</code>、<code>sdk</code>、<code>sdk-minimal</code>、<code>acp</code>。</li><li><strong>bundle（包层）</strong>：配置行 + 所挂代码的分发格式。它最重要的性质写在定义里——&quot;whatever it inserts stays patchable by the layers above it&quot;：bundle 插入的每一行配置，都能被更上层的 patch 覆盖。</li><li><strong>patch（补丁）</strong>：按 <code>id</code> 命中某一行、整体替换它的 config，或插入新行。</li></ul><p>每个 bundle 在自己 <code>package.json</code> 的 <code>dsh</code> 字段里自我声明：</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// packages/bundle/base/package.json（节选）</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dsh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;bundle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;patch&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./cordis.patch.yml&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>层叠顺序是固定的：<strong>空配置起点 → 按 profile 列出的顺序逐层应用 bundle → profile 自己的 <code>cordis.patch.yml</code> → home 级 <code>cordis.patch.yml</code> → 命令行 <code>--patch</code> 覆盖</strong>。<code>dsh-base</code> 是所有主 profile 的第一层，装模型适配器、工具、持久化、沙箱与审批策略、设置、凭据、遥测；<code>dsh-web-app</code> 在其上加浏览器应用，<code>dsh-headless</code> 加一次性 runner，<code>dsh-sdk-app</code> 加 JSON-RPC 服务，<code>dsh-acp-app</code> 加 ACP 自动化服务。</p><p>想知道你这台机器实际会启动哪棵树，有一个官方命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dump-config</span></span></code></pre></div><p>它不启动、不请求模型，只把叠好的配置树打印出来，打印的每一行都能被你自己的 patch 替换。装配还带热重载：<code>base</code> 默认启用 config-only 的 <code>dsh-hmr</code>，改 patch 文件即重载；<code>headless</code>、SDK、ACP 模板关掉它，一次性任务不需要 watcher。</p><h2 id="四、一棵树长出一排产品形态" tabindex="-1">四、一棵树长出一排产品形态 <a class="header-anchor" href="#四、一棵树长出一排产品形态" aria-label="Permalink to &quot;四、一棵树长出一排产品形态&quot;">​</a></h2><p>装配链最有说服力的部分是&quot;减法&quot;。<code>dsh-headless</code> 的 README 定位是&quot;runs one dsh task from the command line and prints the final answer, then exits&quot;——不装 host、不装 HTTP 服务、不装浏览器，同一个 <code>dsh-base</code> 上少装一个面，就变成 CI 里跑一次性任务的命令行工具，<code>--json</code> 输出事件流，<code>--session-id</code> 续会话。五个发行模板加上保留的 desktop 档，全部从同一棵树上装配出来：</p><p><img src="`+p+'" alt="同一棵插件树装配出的产品形态"></p><table tabindex="0"><thead><tr><th>形态</th><th>装配</th><th>用途</th></tr></thead><tbody><tr><td><code>web</code></td><td>base + web-app</td><td>浏览器图形界面</td></tr><tr><td><code>headless</code></td><td>base + headless</td><td>脚本/CI 一次性任务</td></tr><tr><td><code>sdk</code></td><td>base + sdk-app</td><td>TypeScript/Python SDK 的 JSON-RPC 服务</td></tr><tr><td><code>acp</code></td><td>base + acp-app</td><td>自动化协议（ACP）服务</td></tr><tr><td><code>desktop</code></td><td>base + web-app + Electron 壳</td><td>桌面应用（保留 profile，CLI 不可管理）</td></tr><tr><td><code>sdk-minimal</code></td><td>无 base，单一 bundle 独占显式树</td><td>SDK 最小化装配</td></tr></tbody></table><p><code>sdk-minimal</code> 是故意的例外：它不套 <code>dsh-base</code>，由一个 bundle 独占完整的显式 SDK 树——仓库需要证明&quot;不用基础层也能从零组一棵干净的树&quot;。Python SDK 则展示了复用的深度：它的运行时 wheel 直接把 <code>dsh</code> CLI 打包成 <code>deepseek-harness-sdk-runtime-&lt;platform&gt;-&lt;arch&gt;</code>，客户端启动的还是 <code>dsh --profile sdk</code>，Python 侧只暴露 profile 选择和有序 patch 文件。</p><p>仓库还配了一个守门脚本 <code>verify-application-entrypoints</code>：所有受支持的 Node 应用必须走 <code>dsh</code> profile 启动，包的 bin、demo、根脚本全部归入显式分类，任何绕过 <code>dsh</code> 的 Node 应用路径都会被拒绝。&quot;装配即产品&quot;在这里不是口号，是被 CI 强制的纪律。</p><h2 id="五、与三栏对比与阅读路线" tabindex="-1">五、与三栏对比与阅读路线 <a class="header-anchor" href="#五、与三栏对比与阅读路线" aria-label="Permalink to &quot;五、与三栏对比与阅读路线&quot;">​</a></h2><p>把全篇收进一张对照表：</p><table tabindex="0"><thead><tr><th>维度</th><th>OpenCode / Codex / Claude Code</th><th>DeepSeek Harness</th></tr></thead><tbody><tr><td>定位</td><td>终端编程 Agent</td><td>通用 agent harness</td></tr><tr><td>核心抽象</td><td>主循环（runLoop / reactor / QueryEngine）</td><td>Cordis 插件树</td></tr><tr><td>底层</td><td>原生 TS / Rust / Bun</td><td>vendored Cordis 组合框架</td></tr><tr><td>规模</td><td>单包 5 万～51 万行</td><td>307 包 / packages 内约 75 万行</td></tr><tr><td>产品化路径</td><td>一个产品一个形态</td><td>profile/bundle 装配出五种形态</td></tr></tbody></table><p>前三栏把&quot;agent 怎么干活&quot;写进产品中心；<code>dsh</code> 把这个问题外包给装配者，自己只保证每个部件可换、每次注册可回滚、每棵树可审计。两种路线没有高下，一个面向开箱即用，一个面向被任意装配。</p><p>沿着这棵树，后面五篇的路线是：</p><ol><li><strong>Cordis 组合框架</strong>——插件靠什么原语共存：Context、effect、waterfall、Service 注入、scope、Loader。</li><li><strong>agent-loop</strong>——默认驱动怎么跑一个回合：turn/step 事件流、单一 inbox、waterfall 与 serial 的分工。</li><li><strong>会话日志</strong>——模型上下文从哪来：追加式事件日志、<code>deriveMessages()</code> 投影、&quot;model-visible ⟺ logged&quot; 不变量。</li><li><strong>capability 缝</strong>——为什么换一个实现能牵一发动全身：三件套、执行世界、provider 整套迁移。</li><li><strong>扩展的三个极致</strong>——自改 toolset、CC/Codex hooks 翻译桥、跨产品 subagent 委托。</li></ol><p>一句话收束：<strong><code>dsh</code> 不是一个 agent loop，而是一套让任意 agent loop 都能被拼出来的组合框架。</strong></p><h2 id="源码索引" tabindex="-1">源码索引 <a class="header-anchor" href="#源码索引" aria-label="Permalink to &quot;源码索引&quot;">​</a></h2><ul><li><code>docs/architecture.md</code> — Cordis / Profiles and bundles / Application launch / Core packages</li><li><code>packages/README.md</code> — 分组表与依赖规则</li><li><code>pnpm-workspace.yaml</code> — workspace 编制</li><li><code>packages/bundle/base/package.json</code> — <code>dsh.bundle.patch</code> 自我声明</li><li><code>packages/boot/app-boot/README.md</code> — profile 层叠顺序、HMR、启动失败策略</li><li><code>packages/bundle/headless/README.md</code> — 一次性任务模式</li><li><code>packages/bundle/sdk-minimal/</code> — 无 base 的独立树例外</li><li><code>scripts/verify-application-entrypoints.ts</code> — 启动路径守门</li></ul><h2 id="章节小测" tabindex="-1">章节小测 <a class="header-anchor" href="#章节小测" aria-label="Permalink to &quot;章节小测&quot;">​</a></h2>',45)),n(o,{questions:t})])}}});export{k as __pageData,g as default};
